// aim.cpp
// Projects entity head positions to screen and returns a smoothed crosshair
// delta inside a 240px cone radius, for a first-person game on the local machine.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /EHsc aim.cpp /Fe:aim_test.exe
//
// Exported surface:
//   AimInit          – set screen dimensions and smoothing factor
//   AimProjectHead   – world-space head pos -> screen-space pixel pos
//   AimComputeDelta  – return smoothed (dx, dy) toward nearest target in cone

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <math.h>
#include <float.h>
#include <stdint.h>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

struct AimConfig
{
    int   screenW;          // pixels
    int   screenH;          // pixels
    float fovYRad;          // vertical field-of-view in radians
    float smoothFactor;     // 0 < s <= 1  (1 = instant, 0.05 = very smooth)
    float coneRadiusPx;     // candidate entities outside this radius are ignored
};

struct AimResult
{
    bool  valid;            // false when no target is in cone
    float dx;               // pixels to move cursor right  (may be negative)
    float dy;               // pixels to move cursor down   (may be negative)
};

// ---------------------------------------------------------------------------
// Module state
// ---------------------------------------------------------------------------

static AimConfig  g_cfg;
static Vec2       g_prevDelta;   // last emitted delta (for smoothing)
static bool       g_inited;

// ---------------------------------------------------------------------------
// AimInit
// ---------------------------------------------------------------------------
// Call once (or whenever resolution / FOV changes).
// smoothFactor: fraction of the remaining error closed per frame.
//   Typical values: 0.08 (subtle) … 0.30 (responsive).
// coneRadiusPx: entities whose projected head is farther than this many pixels
//   from screen-centre are skipped.  Pass 240.0f to match the spec.
// ---------------------------------------------------------------------------
extern "C" void AimInit(int screenW, int screenH,
                        float fovYRad,
                        float smoothFactor,
                        float coneRadiusPx)
{
    g_cfg.screenW      = screenW;
    g_cfg.screenH      = screenH;
    g_cfg.fovYRad      = fovYRad;
    g_cfg.smoothFactor = (smoothFactor > 0.0f && smoothFactor <= 1.0f)
                             ? smoothFactor : 0.10f;
    g_cfg.coneRadiusPx = coneRadiusPx;
    g_prevDelta        = {0.0f, 0.0f};
    g_inited           = true;
}

// ---------------------------------------------------------------------------
// AimProjectHead
// ---------------------------------------------------------------------------
// Projects a single world-space head position onto the screen.
//
// viewMatrix: column-major 4x4 view transform (world-to-camera).
//   viewMatrix[0..3]  = first column, etc.
//   The caller builds this from the local player's yaw/pitch/position.
//
// Returns the screen pixel position.  If the point is behind the camera
// (z >= 0 in view space after projection) outPos is set to {-1,-1} and the
// function returns false.
// ---------------------------------------------------------------------------
extern "C" bool AimProjectHead(const Vec3*  headWorldPos,
                                const float  viewMatrix[16],
                                Vec2*        outPos)
{
    if (!g_inited || !headWorldPos || !viewMatrix || !outPos)
        return false;

    // Transform world position into camera / clip space.
    // viewMatrix is column-major:  M[col*4 + row]
    float wx = headWorldPos->x;
    float wy = headWorldPos->y;
    float wz = headWorldPos->z;

    // Camera-space position  (right-handed: +x right, +y up, -z forward)
    float cx = viewMatrix[0]*wx + viewMatrix[4]*wy + viewMatrix[8]*wz  + viewMatrix[12];
    float cy = viewMatrix[1]*wx + viewMatrix[5]*wy + viewMatrix[9]*wz  + viewMatrix[13];
    float cz = viewMatrix[2]*wx + viewMatrix[6]*wy + viewMatrix[10]*wz + viewMatrix[14];
    // w component for perspective
    float cw = viewMatrix[3]*wx + viewMatrix[7]*wy + viewMatrix[11]*wz + viewMatrix[15];

    // Behind camera?
    if (cw <= 0.0f)
    {
        outPos->x = -1.0f;
        outPos->y = -1.0f;
        return false;
    }

    // Perspective division -> NDC [-1, 1]
    float aspect = (float)g_cfg.screenW / (float)g_cfg.screenH;
    float tanHalfFovY = tanf(g_cfg.fovYRad * 0.5f);

    float ndcX =  cx / (cw * aspect * tanHalfFovY);
    float ndcY = -cy / (cw * tanHalfFovY);           // flip y: +y is down on screen

    // NDC -> pixel
    outPos->x = ( ndcX * 0.5f + 0.5f) * (float)g_cfg.screenW;
    outPos->y = ( ndcY * 0.5f + 0.5f) * (float)g_cfg.screenH;

    (void)cz; // depth available if needed for occlusion checks

    return true;
}

// ---------------------------------------------------------------------------
// AimComputeDelta
// ---------------------------------------------------------------------------
// Given an array of projected head positions (screen pixels), finds the
// nearest visible candidate within the configured cone, computes the raw
// delta from screen centre, applies exponential smoothing, and returns it.
//
// projectedHeads : array of Vec2 screen positions from AimProjectHead.
// count          : number of elements.
// visibleFlags   : optional bool array; if non-null, entry [i]==false skips
//                  that target.  Pass null to treat all as visible.
//
// The function uses screen-centre as the aiming origin; callers that place
// the crosshair elsewhere should subtract the offset themselves.
// ---------------------------------------------------------------------------
extern "C" AimResult AimComputeDelta(const Vec2* projectedHeads,
                                     int         count,
                                     const bool* visibleFlags)
{
    AimResult result = {false, 0.0f, 0.0f};

    if (!g_inited || !projectedHeads || count <= 0)
        return result;

    float cx = (float)g_cfg.screenW  * 0.5f;
    float cy = (float)g_cfg.screenH  * 0.5f;
    float coneR2 = g_cfg.coneRadiusPx * g_cfg.coneRadiusPx;

    float bestDist2 = FLT_MAX;
    int   bestIdx   = -1;

    for (int i = 0; i < count; ++i)
    {
        if (visibleFlags && !visibleFlags[i])
            continue;

        float px = projectedHeads[i].x;
        float py = projectedHeads[i].y;

        // Skip off-screen / behind-camera markers
        if (px < 0.0f && py < 0.0f)
            continue;

        float dx = px - cx;
        float dy = py - cy;
        float d2 = dx*dx + dy*dy;

        if (d2 <= coneR2 && d2 < bestDist2)
        {
            bestDist2 = d2;
            bestIdx   = i;
        }
    }

    if (bestIdx < 0)
    {
        // No target in cone – let previous delta decay to zero
        g_prevDelta.x *= (1.0f - g_cfg.smoothFactor);
        g_prevDelta.y *= (1.0f - g_cfg.smoothFactor);
        // Don't report as valid; zero out if negligible
        if (fabsf(g_prevDelta.x) < 0.1f && fabsf(g_prevDelta.y) < 0.1f)
            g_prevDelta = {0.0f, 0.0f};
        return result;
    }

    float rawDx = projectedHeads[bestIdx].x - cx;
    float rawDy = projectedHeads[bestIdx].y - cy;

    // Exponential smoothing toward target delta
    float s = g_cfg.smoothFactor;
    g_prevDelta.x = g_prevDelta.x + s * (rawDx - g_prevDelta.x);
    g_prevDelta.y = g_prevDelta.y + s * (rawDy - g_prevDelta.y);

    result.valid = true;
    result.dx    = g_prevDelta.x;
    result.dy    = g_prevDelta.y;
    return result;
}

// ---------------------------------------------------------------------------
// Standalone smoke test
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <stdio.h>
#include <assert.h>

// Build a trivial identity-ish view matrix (camera at origin, looking -Z)
static void MakeIdentityView(float m[16])
{
    // Column-major identity
    for (int i = 0; i < 16; ++i) m[i] = 0.0f;
    m[0] = m[5] = m[10] = m[15] = 1.0f;
    // Flip z column so camera looks down -Z (OpenGL convention)
    m[10] = -1.0f;
}

int main(void)
{
    // 1920x1080, 90-degree vertical FOV, smooth=0.15, cone=240px
    AimInit(1920, 1080,
            (float)(3.14159265358979323846 / 2.0),   // 90 deg
            0.15f,
            240.0f);

    float view[16];
    MakeIdentityView(view);

    // Target 2 metres in front of camera, slightly right and up
    Vec3 head = {0.3f, 0.5f, -2.0f};
    Vec2 screen = {-1.0f, -1.0f};

    bool ok = AimProjectHead(&head, view, &screen);
    printf("AimProjectHead: ok=%d  screen=(%.1f, %.1f)\n", ok, screen.x, screen.y);
    assert(ok);
    assert(screen.x > 960.0f);   // slightly right of centre
    assert(screen.y < 540.0f);   // slightly above centre

    // Run a few delta frames
    bool vis[1] = {true};
    for (int frame = 0; frame < 6; ++frame)
    {
        AimResult r = AimComputeDelta(&screen, 1, vis);
        printf("Frame %d: valid=%d  delta=(%.2f, %.2f)\n",
               frame, r.valid, r.dx, r.dy);
        assert(r.valid);
    }

    // Target outside cone (far off-screen)
    Vec3 farHead = {5.0f, 0.0f, -2.0f};
    Vec2 farScreen = {-1.0f, -1.0f};
    AimProjectHead(&farHead, view, &farScreen);
    printf("Far head screen pos: (%.1f, %.1f)\n", farScreen.x, farScreen.y);
    AimResult rFar = AimComputeDelta(&farScreen, 1, vis);
    printf("Outside cone: valid=%d\n", rFar.valid);
    // May or may not be valid depending on how far it lands; just print.

    printf("Smoke test passed.\n");
    return 0;
}
#endif // AIM_SMOKE
